  p.innerHTML='<div class="card"><h2>'+esc(d.title)+' <span class="tag">'+d.level+'</span> <span class="tag">'+d.total+' marks</span></h2><div class="btns noprint"><button data-a="back">Edit details</button><label><input type="checkbox" id="key"> Show answer key</label><button data-a="print">Print</button><button data-a="addBankQuestions">Add approved library questions</button><button class="go" data-a="save" data-id="1">Save and publish</button><button class="p" data-a="save" data-id="0">Save as draft</button></div><div class="msg" id="sm2"></div></div><div id="sheet">'+storyHTML(d.story)+'<div class="card">'+list(d.Q,false)+'</div></div>';
