 toggleAccessibility:id=>{document.body.classList.toggle(id)},
 previewCsv:()=>{const f=$('#pupil-csv').files[0];if(!f)return toast('Choose a CSV file first.');if(!window.Papa)return toast('CSV reader is not available.');Papa.parse(f,{header:true,skipEmptyLines:true,complete:r=>{const rows=r.data.map(x=>({name:x.name||x.Name,username:x.username||x.Username,level:x.class||x.level||x.Class}));const invalid=rows.filter(x=>!x.name||!x.username||!/^P\.[1-6]$/.test(x.level));const existing=new Set((CACHE.U||[]).map(x=>String(x.username).toLowerCase())),seen=new Set(),dupes=[];const candidates=rows.filter(x=>x.name&&x.username&&/^P\.[1-6]$/.test(x.level));CACHE.importRows=candidates.filter(x=>{const k=String(x.username).toLowerCase();if(existing.has(k)||seen.has(k)){dupes.push(x.username);return false}seen.add(k);return true});$('#csv-preview').innerHTML='<p>'+CACHE.importRows.length+' ready to import; '+invalid.length+' invalid rows; '+dupes.length+' duplicate usernames will be skipped.</p>'+'<div class="scroll"><table><tr><th>Name</th><th>Username</th><th>Class</th></tr>'+CACHE.importRows.slice(0,30).map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+esc(x.username)+'</td><td>'+esc(x.level)+'</td></tr>').join('')+'</table></div><button class="go" data-a="importCsv" '+(!CACHE.importRows.length?'disabled':'')+'>Import valid pupils</button>'}})},
 importCsv:async()=>{try{const r=await api('POST','/users/import',{rows:CACHE.importRows||[]});app.innerHTML='<div class="card"><h2>Starting password sheet</h2><p>Created '+r.created+' pupil accounts. Skipped '+r.skipped+' duplicate usernames. Print this sheet and distribute credentials privately. Pupils must change their password at first sign-in.</p><div class="scroll"><table><tr><th>Pupil</th><th>Username</th><th>Class</th><th>Starting password</th></tr>'+r.credentials.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+esc(x.username)+'</td><td>'+esc(x.level)+'</td><td><b>'+esc(x.password)+'</b></td></tr>').join('')+'</table></div><button class="go" data-a="print">Print password sheet</button><button data-a="tab" data-id="pupils">Back to people</button></div>'}catch(e){toast(e.message)}},
 pin:async id=>{const v=prompt('Enter the new PIN or password (pupils: 4+ characters, teachers: 8+).');if(!v)return;try{await api('PATCH','/users/'+id,{password:v});toast('Password changed.')}catch(e){toast(e.message)}},
 tog:async id=>{const u=CACHE.U.find(x=>x.id==id);await api('PATCH','/users/'+id,{status:u.status==='approved'?'disabled':'approved'});await pend();shell();tPupils()},
 appr:async id=>{const r=document.querySelector('[data-row="'+id+'"]'),l=r.querySelector('.ap-l')?r.querySelector('.ap-l').value:[...r.querySelectorAll('.ap-c:checked')].map(x=>x.value).join(',');if(!l)return toast('Choose at least one class.');try{await api('PATCH','/users/'+id,{status:'approved',level:l});toast('Approved.');tApprove()}catch(e){toast(e.message)}},
