async function pHome(){wait();const T=await api('GET','/tests'),R=await api('GET','/results'),rid={};R.forEach(r=>rid[r.title]=r.id);const n=R.reduce((s,r)=>s+stars(pc(r.got,r.total)),0);
 app.innerHTML='<div class="card noprint"><b>Reading display</b> <button class="sm" data-a="toggleAccessibility" data-id="large-text">Larger text</button> <button class="sm" data-a="toggleAccessibility" data-id="easy-read">Easy-reading font</button> <button class="sm" data-a="toggleAccessibility" data-id="high-contrast">High contrast</button></div><div class="hero"><div class="book">📖</div><h1>Hello, '+esc(ME.name.split(' ')[0])+'!</h1><p>You have collected <b class="stars">'+'⭐'.repeat(Math.min(n,12))+(n>12?' +'+(n-12):'')+(n?'':'none yet')+'</b></p></div>'+(T.length?'<div class="grid">'+T.map((t,i)=>{const d=t.status==='done',s=d?stars(pc(t.got,t.total)):0;return'<div class="cover" style="'+cv(i)+'"><div><div class="em">'+EM[t.id%8]+'</div><h3>'+esc(t.title)+'</h3><span class="tag">'+esc(t.level)+' · '+t.total+' marks</span></div><div>'+(d?'<div class="stars">'+(s?'⭐'.repeat(s):'🌱')+'</div><p style="margin:2px 0">'+t.got+'/'+t.total+' ('+pc(t.got,t.total)+'%)</p><button class="sm" data-a="rev" data-id="'+(R.find(r=>r.title===t.title)||{}).id+'">See corrections</button>':'<button data-a="start" data-id="'+t.id+'">'+(t.status?'Continue':'Start reading')+' →</button>')+'</div></div>'}).join('')+'</div>':'<div class="card"><h2>No stories yet</h2><p class="lead">Your teacher has not shared a story yet. Check again soon!</p></div>')}
async function pProg(){wait();const[R,P]=await Promise.all([api('GET','/results'),api('GET','/progress')]);const S={};R.forEach(r=>Object.keys(r.by).forEach(k=>{S[k]=S[k]||{g:0,m:0};S[k].g+=r.by[k].g;S[k].m+=r.by[k].m}));app.innerHTML='<div class="grid"><div class="stat"><b>'+P.books_read+'</b>Books read</div><div class="stat"><b>'+P.points+'</b>Points</div><div class="stat"><b>'+P.streak+'</b>Reading streak</div></div><div class="card"><h2>My rewards</h2><p>'+((P.badges||[]).map(x=>'🏅 '+esc(x)).join(' · ')||'Keep reading to earn badges.')+'</p></div><div class="card"><h2>My Bloom’s levels</h2>'+(R.length?BL.filter(k=>S[k]).map(k=>{const p=pc(S[k].g,S[k].m);return'<div class="sec"><span>'+k+'</span><span>'+p+'% '+(p>=70?'⭐ Strong':'🌱 Keep practising')+'</span></div><div class="bar"><i style="width:'+p+'%"></i></div>'}).join(''):'<p class="lead">Finish a test to see how you are growing.</p>')+'</div><div class="card"><h2>Assessment history</h2>'+(R.length?'<div class="scroll"><table><tr><th>Test</th><th>Score</th><th>Date</th></tr>'+R.map(r=>'<tr><td>'+esc(r.title)+'</td><td>'+r.got+'/'+r.total+'</td><td>'+dt(r.finished_at)+'</td></tr>').join('')+'</table></div>':'<p>No completed tests yet.</p>')+'</div>'}

